solution.solution.rs:
fn to_celsius(fahrenheit: f64) -> f64 {
    (fahrenheit - 32.0) * 5.0 / 9.0
}

fn average(a: i32, b: i32, c: i32) -> f64 {
    (a as f64 + b as f64 + c as f64) / 3.0
}

fn to_cents(euros: f64) -> i64 {
    (euros * 100.0).round() as i64
}

fn add_volume(volume: u8, change: i16) -> u8 {
    (volume as i16 + change).clamp(0, 100) as u8
}

fn checked_area(width: u32, height: u32) -> Option<u32> {
    width.checked_mul(height)
}

unitTests:
test("Fahrenheit to Celsius", || {
    check_near(to_celsius(212.0), 100.0, 1e-9);
    check_near(to_celsius(-40.0), -40.0, 1e-9);
    check_near(to_celsius(98.6), 37.0, 1e-9);
});

test("an exact average", || {
    check_near(average(1, 2, 2), 5.0 / 3.0, 1e-9);
    check_near(average(i32::MAX, i32::MAX, i32::MAX), i32::MAX as f64, 1e-3);
    check_near(average(-1, 0, 0), -1.0 / 3.0, 1e-9);
});

test("euros to cents", || {
    check_eq(to_cents(19.99), 1999);
    check_eq(to_cents(0.29), 29);
    check_eq(to_cents(0.07), 7);
});

test("volume stays in range", || {
    check_eq(add_volume(50, 30), 80);
    check_eq(add_volume(90, 30), 100);
    check_eq(add_volume(10, -30), 0);
    check_eq(add_volume(100, 0), 100);
});

test("checked multiplication", || {
    check_eq(checked_area(1000, 2000), Some(2_000_000));
    check_eq(checked_area(70_000, 70_000), None);
    check_eq(checked_area(0, u32::MAX), Some(0));
});

